#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
struct Button {
  uint8_t pin;
  bool raw;
  bool stable;
  unsigned long changed;
};
Button startButton = {2, HIGH, HIGH, 0};
Button clearButton = {3, HIGH, HIGH, 0};
bool running = false;
bool alarming = false;
unsigned long elapsed = 0;
unsigned long previous = 0;
unsigned long alarmStarted = 0;
unsigned long shown = 0xFFFFFFFFUL;

bool pressed(Button &b, unsigned long now) {
  bool value = digitalRead(b.pin);
  if (value != b.raw) {
    b.raw = value;
    b.changed = now;
  }
  if (b.stable != b.raw && now - b.changed >= 25) {
    b.stable = b.raw;
    return b.stable == LOW;
  }
  return false;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  noTone(6);
  display.setBrightness(7);
  display.showNumberDec(0, false);
  shown = 0;
  previous = millis();
}

void loop() {
  unsigned long now = millis();
  unsigned long delta = now - previous;
  previous = now;
  unsigned long before = elapsed;
  if (running) elapsed += delta;
  if (before < 60000UL && elapsed >= 60000UL) {
    tone(6, 2000);
    alarming = true;
    alarmStarted = now;
  }
  if (alarming && now - alarmStarted >= 1000UL) {
    noTone(6);
    alarming = false;
  }
  if (pressed(startButton, now)) running = !running;
  if (pressed(clearButton, now)) {
    elapsed = 0;
    alarming = false;
    noTone(6);
  }
  unsigned long seconds = elapsed / 1000UL;
  if (seconds != shown) {
    display.showNumberDec(seconds % 10000UL, false);
    shown = seconds;
  }
}
